27	func (f *fakeStorage) GetOverview(_ context.Context, tenantID string) (*clickhouse.OverviewStats, error) {
28		f.mu.Lock()
29		defer f.mu.Unlock()
30	
31		stats := &clickhouse.OverviewStats{}
32		cmdMap := make(map[string]*clickhouse.CommandStat)
33	
34		for _, e := range f.events {
35			if e.TenantID != tenantID {
36				continue
37			}
38			stats.TotalInputTokens += e.InputTokens
39			stats.TotalOutputTokens += e.OutputTokens
40			stats.TotalSaved += e.TokensSaved
41			stats.EventCount++
42	
43			if cs, ok := cmdMap[e.Command]; ok {
44				cs.Saved += e.TokensSaved
45				cs.Count++
46			} else {
47				cmdMap[e.Command] = &clickhouse.CommandStat{
48					Command: e.Command,
49					Saved:   e.TokensSaved,
50					Count:   1,
51				}
52			}
53		}
54	
55		if stats.TotalInputTokens > 0 {
56			stats.SavingsPct = float64(stats.TotalSaved) / float64(stats.TotalInputTokens) * 100
57		}
58	
59		for _, cs := range cmdMap {
60			stats.TopCommands = append(stats.TopCommands, *cs)
61		}
62	
63		return stats, nil
64	}
