66	func (f *fakeStorage) GetProjects(_ context.Context, tenantID string) ([]clickhouse.ProjectSummary, error) {
67		f.mu.Lock()
68		defer f.mu.Unlock()
69	
70		projMap := make(map[string]*clickhouse.ProjectSummary)
71		for _, e := range f.events {
72			if e.TenantID != tenantID {
73				continue
74			}
75			p, ok := projMap[e.ProjectDir]
76			if !ok {
77				p = &clickhouse.ProjectSummary{ProjectDir: e.ProjectDir}
78				projMap[e.ProjectDir] = p
79			}
80			p.TotalSaved += e.TokensSaved
81			p.TotalInput += e.InputTokens
82			p.EventCount++
83			p.LastEventAt = e.Timestamp.Format(time.RFC3339)
84		}
85	
86		for _, p := range projMap {
87			if p.TotalInput > 0 {
88				p.SavingsPct = float64(p.TotalSaved) / float64(p.TotalInput) * 100
89			}
90		}
91	
92		var result []clickhouse.ProjectSummary
93		for _, p := range projMap {
94			result = append(result, *p)
95		}
96		return result, nil
97	}
