99	func (f *fakeStorage) GetProjectStats(_ context.Context, tenantID, projectDir string) (*clickhouse.ProjectStats, error) {
100		f.mu.Lock()
101		defer f.mu.Unlock()
102	
103		ps := &clickhouse.ProjectStats{ProjectDir: projectDir}
104		for _, e := range f.events {
105			if e.TenantID != tenantID || e.ProjectDir != projectDir {
106				continue
107			}
108			ps.Summary.TotalSaved += e.TokensSaved
109			ps.Summary.TotalInput += e.InputTokens
110			ps.Summary.EventCount++
111			ps.Summary.LastEventAt = e.Timestamp.Format(time.RFC3339)
112		}
113		ps.Summary.ProjectDir = projectDir
114		if ps.Summary.TotalInput > 0 {
115			ps.Summary.SavingsPct = float64(ps.Summary.TotalSaved) / float64(ps.Summary.TotalInput) * 100
116		}
117		return ps, nil
118	}
