120	func (f *fakeStorage) GetSavingsTrend(_ context.Context, tenantID string, days int) ([]clickhouse.DailySavings, error) {
121		f.mu.Lock()
122		defer f.mu.Unlock()
123	
124		dayMap := make(map[string]*clickhouse.DailySavings)
125		cutoff := time.Now().AddDate(0, 0, -days)
126	
127		for _, e := range f.events {
128			if e.TenantID != tenantID || e.Timestamp.Before(cutoff) {
129				continue
130			}
131			day := e.Timestamp.Format("2006-01-02")
132			d, ok := dayMap[day]
133			if !ok {
134				d = &clickhouse.DailySavings{Day: day}
135				dayMap[day] = d
136			}
137			d.TotalSaved += e.TokensSaved
138			d.TotalInput += e.InputTokens
139			d.EventCount++
140			if e.EventType == "compression" {
141				d.Compression += e.TokensSaved
142			}
143			if e.EventType == "dedup" {
144				d.Dedup += e.TokensSaved
145			}
146		}
147	
148		var result []clickhouse.DailySavings
149		for _, d := range dayMap {
150			result = append(result, *d)
151		}
152		return result, nil
153	}
154	
155	func (f *fakeStorage) eventCount() int {
156		f.mu.Lock()
157		defer f.mu.Unlock()
158		return len(f.events)
159	}
