19	func withTenantAuth(next http.Handler) http.Handler {
20		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
21			tenantID := ""
22	
23			if auth := r.Header.Get("Authorization"); strings.HasPrefix(auth, "Bearer ") {
24				token := strings.TrimPrefix(auth, "Bearer ")
25				if tid := extractTenantFromJWT(token); tid != "" {
