27				}
28			}
29	
30			if tenantID == "" {
31				if tid := r.Header.Get("X-Tenant-ID"); tid != "" {
32					tenantID = tid
33				}
34			}
35	
36			if tenantID == "" {
37				tenantID = "default"
38			}
39	
40			ctx := context.WithValue(r.Context(), tenantCtxKey, tenantID)
41			next.ServeHTTP(w, r.WithContext(ctx))
42		})
