52	func extractTenantFromJWT(token string) string {
53		parts := strings.Split(token, ".")
54		if len(parts) != 3 {
55			return ""
56		}
57	
58		payload, err := base64.RawURLEncoding.DecodeString(parts[1])
59		if err != nil {
60			return ""
61		}
62	
63		var claims struct {
64			TenantID string `json:"tenant_id"`
65			OrgID    string `json:"org_id"`
66		}
67		if err := json.Unmarshal(payload, &claims); err != nil {
68			return ""
69		}
70	
71		if claims.TenantID != "" {
72			return claims.TenantID
73		}
74		return claims.OrgID
