11		if allowedOrigin == "" {
12			allowedOrigin = "http://localhost:3000"
13		}
14	
15		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
16			origin := r.Header.Get("Origin")
17			if origin != "" && originAllowed(origin, allowedOrigin) {
18				w.Header().Set("Access-Control-Allow-Origin", origin)
19				w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
20				w.Header().Set("Access-Control-Allow-Headers", "Content-Type, Content-Encoding, Authorization, X-Tenant-ID")
21				w.Header().Set("Access-Control-Max-Age", "3600")
22			}
23	
24			if r.Method == http.MethodOptions {
25				w.WriteHeader(http.StatusNoContent)
26				return
27			}
28	
29			next.ServeHTTP(w, r)
30		})
31	}
