9	type bucket struct {
10		tokens    float64
11		lastFill  time.Time
12		ratePerSec float64
13		capacity  float64
14	}
15	
16	type rateLimiter struct {
17		mu      sync.Mutex
18		buckets map[string]*bucket
19		free    float64
20		pro     float64
21	}
22	
23	func newRateLimiter() *rateLimiter {
24		rl := &rateLimiter{
25			buckets: make(map[string]*bucket),
26			free:    100.0 / 60.0,
27			pro:     10000.0 / 60.0,
28		}
29		go rl.cleanup()
30		return rl
31	}
32	
33	func (rl *rateLimiter) cleanup() {
34		ticker := time.NewTicker(5 * time.Minute)
35		defer ticker.Stop()
36		for range ticker.C {
37			rl.mu.Lock()
38			cutoff := time.Now().Add(-10 * time.Minute)
39			for k, b := range rl.buckets {
40				if b.lastFill.Before(cutoff) {
41					delete(rl.buckets, k)
42				}
43			}
44			rl.mu.Unlock()
45		}
46	}
47	
48	func (rl *rateLimiter) allow(tenantID string) bool {
49		rl.mu.Lock()
50		defer rl.mu.Unlock()
51	
52		b, ok := rl.buckets[tenantID]
53		if !ok {
54			rate := rl.free
55			b = &bucket{
56				tokens:    rate * 60,
57				lastFill:  time.Now(),
58				ratePerSec: rate,
59				capacity:  rate * 60,
60			}
61			rl.buckets[tenantID] = b
62		}
63	
64		now := time.Now()
65		elapsed := now.Sub(b.lastFill).Seconds()
66		b.tokens += elapsed * b.ratePerSec
67		if b.tokens > b.capacity {
68			b.tokens = b.capacity
69		}
70		b.lastFill = now
71	
72		if b.tokens < 1 {
73			return false
74		}
75		b.tokens--
76		return true
77	}
78	
79	func withRateLimit(rl *rateLimiter) func(http.Handler) http.Handler {
80		return func(next http.Handler) http.Handler {
81			return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
82				tenantID := tenantFromCtx(r)
83	
84				if !rl.allow(tenantID) {
85					w.Header().Set("Retry-After", "60")
86					http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
87					return
88				}
89	
90				next.ServeHTTP(w, r)
91			})
92		}
93	}
